DROP TRIGGER IF EXISTS notification_purchase_quote_created_deferred ON public.purchase_quote_requests;
CREATE CONSTRAINT TRIGGER notification_purchase_quote_created_deferred
  AFTER INSERT ON public.purchase_quote_requests
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION public.notification_purchase_quote_created();

CREATE OR REPLACE FUNCTION public.notification_purchase_quote_status_changed()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_title text;
  v_title_ar text;
  v_message text;
  v_message_ar text;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;

  CASE NEW.status
    WHEN 'contacted' THEN
      v_title := 'Your request is being reviewed';
      v_title_ar := 'طلبك قيد المراجعة';
      v_message := format('The Eventies team has started reviewing and following up on your request %s.', NEW.request_number);
      v_message_ar := format('بدأ فريق Eventies بمراجعة ومتابعة طلبك %s.', NEW.request_number);
    WHEN 'quoted' THEN
      v_title := 'Your quote is ready';
      v_title_ar := 'عرض السعر الخاص بك جاهز';
      v_message := 'Your request has been quoted. Our team will contact you.';
      v_message_ar := 'تم تجهيز عرض السعر لطلبك. سيتواصل معك فريقنا.';
    WHEN 'won' THEN
      v_title := 'Your request has been confirmed';
      v_title_ar := 'تم تأكيد طلبك';
      v_message := format('Your quote request %s has been confirmed and is moving forward.', NEW.request_number);
      v_message_ar := format('تم تأكيد طلب عرض السعر %s وسيتم استكمال الإجراءات.', NEW.request_number);
    WHEN 'lost' THEN
      v_title := 'Request closed';
      v_title_ar := 'تم إغلاق الطلب';
      v_message := format('Your quote request %s has been closed.', NEW.request_number);
      v_message_ar := format('تم إغلاق طلب عرض السعر %s.', NEW.request_number);
    WHEN 'rejected' THEN
      v_title := 'Quote request not approved';
      v_title_ar := 'لم تتم الموافقة على طلب عرض السعر';
      v_message := format('Your quote request %s could not be approved.', NEW.request_number);
      v_message_ar := format('تعذر قبول طلب عرض السعر %s.', NEW.request_number);
    ELSE
      RETURN NEW;
  END CASE;

  PERFORM public.enqueue_notification(
    NEW.profile_id,
    'quote_status_' || NEW.status,
    v_title,
    v_message,
    v_title_ar,
    v_message_ar,
    'normal',
    'purchase_quote',
    NEW.id::text,
    '/my-requests/' || NEW.request_number,
    jsonb_build_object('request_number', NEW.request_number, 'status', NEW.status),
    NULL,
    'quote:' || NEW.id::text || ':status:' || NEW.status,
    false
  );

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS notification_purchase_quote_status_changed_after_update ON public.purchase_quote_requests;
CREATE TRIGGER notification_purchase_quote_status_changed_after_update
  AFTER UPDATE OF status ON public.purchase_quote_requests
  FOR EACH ROW
  WHEN (OLD.status IS DISTINCT FROM NEW.status)
  EXECUTE FUNCTION public.notification_purchase_quote_status_changed();

-- --------------------------------------------------------------------------
-- Contact form notifications
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.notification_contact_submitted()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_subject text;
  v_recipient record;
  v_submitter_role text;
BEGIN
  SELECT p.title INTO v_subject
  FROM public.products p
  WHERE p.id = NEW.product_id;

  v_subject := COALESCE(NULLIF(v_subject, ''), NULLIF(NEW.product_slug, ''), 'General inquiry');

  FOR v_recipient IN
    SELECT p.id
    FROM public.profiles p
    WHERE p.role IN ('admin', 'superadmin')
  LOOP
    PERFORM public.enqueue_notification(
      v_recipient.id,
      'new_contact_inquiry',
      'New contact inquiry',
      format('%s submitted a new contact inquiry about %s.', NEW.name, v_subject),
      'استفسار تواصل جديد',
      format('أرسل %s استفسار تواصل جديد حول %s.', NEW.name, v_subject),
      'high',
      'contact_submission',
      NEW.id::text,
      '/admin/contacts?submission=' || NEW.id::text,
      jsonb_build_object('contact_name', NEW.name, 'subject', v_subject),
      NULL,
      'contact:' || NEW.id::text || ':created:admin',
      false
    );
  END LOOP;

  IF NEW.submitter_profile_id IS NOT NULL THEN
    SELECT p.role INTO v_submitter_role
    FROM public.profiles p
    WHERE p.id = NEW.submitter_profile_id;

    IF COALESCE(v_submitter_role, 'user') NOT IN ('admin', 'superadmin') THEN
      PERFORM public.enqueue_notification(
        NEW.submitter_profile_id,
        'contact_submitted',
        'Inquiry received',
        'Your contact inquiry has been submitted successfully.',
        'تم استلام استفسارك',
        'تم إرسال استفسار التواصل الخاص بك بنجاح.',
        'normal',
        'contact_submission',
        NEW.id::text,
        '/contact',
        jsonb_build_object('subject', v_subject),
        NULL,
        'contact:' || NEW.id::text || ':created:client',
        false
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS notification_contact_submitted_after_insert ON public.contact_submissions;
CREATE TRIGGER notification_contact_submitted_after_insert
  AFTER INSERT ON public.contact_submissions
  FOR EACH ROW EXECUTE FUNCTION public.notification_contact_submitted();

-- --------------------------------------------------------------------------
-- Live Chat notifications
-- Noise control: one notification row per conversation/direction/recipient.
-- A new message refreshes that row and makes it unread again.
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.notification_chat_message_created()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_conversation public.chat_conversations%ROWTYPE;
  v_sender_name text;
  v_recipient record;
BEGIN
  SELECT * INTO v_conversation
  FROM public.chat_conversations c
  WHERE c.id = NEW.conversation_id;

  IF v_conversation.id IS NULL THEN RETURN NEW; END IF;

  IF NEW.sender_type = 'customer' THEN
    SELECT COALESCE(NULLIF(p.name, ''), NULLIF(p.email, ''), 'A customer')
    INTO v_sender_name
    FROM public.profiles p
    WHERE p.id = v_conversation.customer_id;

    FOR v_recipient IN
      SELECT p.id
      FROM public.profiles p
      WHERE p.role = 'superadmin'
    LOOP
      PERFORM public.enqueue_notification(
        v_recipient.id,
        'chat_customer_message',
        'New customer message',
        format('%s sent a new chat message.', COALESCE(v_sender_name, 'A customer')),
        'رسالة جديدة من عميل',
        format('أرسل %s رسالة جديدة في المحادثة.', COALESCE(v_sender_name, 'عميل')),
        'high',
        'chat_conversation',
        NEW.conversation_id::text,
        '/admin/chats?conversation=' || NEW.conversation_id::text,
        jsonb_build_object('conversation_id', NEW.conversation_id, 'message_id', NEW.id),
        NEW.sender_id,
        'chat:' || NEW.conversation_id::text || ':customer-to-super',
        true
      );
    END LOOP;
  ELSIF NEW.sender_type = 'superadmin' THEN
    PERFORM public.enqueue_notification(
      v_conversation.customer_id,
      'chat_superadmin_reply',
      'New message from Eventies',
      'You have a new reply from the Eventies team.',
      'رسالة جديدة من Eventies',
      'لديك رد جديد من فريق Eventies.',
      'normal',
      'chat_conversation',
      NEW.conversation_id::text,
      '/?supportChat=' || NEW.conversation_id::text,
      jsonb_build_object('conversation_id', NEW.conversation_id, 'message_id', NEW.id),
      NEW.sender_id,
      'chat:' || NEW.conversation_id::text || ':super-to-customer',
      true
    );
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS notification_chat_message_created_after_insert ON public.chat_messages;
CREATE TRIGGER notification_chat_message_created_after_insert
  AFTER INSERT ON public.chat_messages
  FOR EACH ROW EXECUTE FUNCTION public.notification_chat_message_created();

-- --------------------------------------------------------------------------
-- Super Admin custom broadcast APIs
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.preview_notification_audience(
  p_clients boolean,
  p_admins boolean,
  p_superadmins boolean
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_clients bigint;
  v_admins bigint;
  v_superadmins bigint;
  v_total bigint;
BEGIN
  IF NOT public.is_superadmin() THEN
    RAISE EXCEPTION 'Super Admin access required' USING ERRCODE = '42501';
  END IF;

  SELECT count(*) FILTER (WHERE COALESCE(p.role, 'user') NOT IN ('admin', 'superadmin')),
         count(*) FILTER (WHERE p.role = 'admin'),
         count(*) FILTER (WHERE p.role = 'superadmin')
  INTO v_clients, v_admins, v_superadmins
  FROM public.profiles p;

  SELECT count(*) INTO v_total
  FROM public.profiles p
  WHERE (p_clients AND COALESCE(p.role, 'user') NOT IN ('admin', 'superadmin'))
     OR (p_admins AND p.role = 'admin')
     OR (p_superadmins AND p.role = 'superadmin');

  RETURN jsonb_build_object(
    'clients', CASE WHEN p_clients THEN v_clients ELSE 0 END,
    'admins', CASE WHEN p_admins THEN v_admins ELSE 0 END,
    'superadmins', CASE WHEN p_superadmins THEN v_superadmins ELSE 0 END,
    'total', v_total
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.send_custom_notification(
  p_title text,
  p_message text,
  p_clients boolean,
  p_admins boolean,
  p_superadmins boolean,
  p_target_url text DEFAULT NULL,
  p_type text DEFAULT 'custom'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_actor_name text;
  v_actor_email text;
  v_broadcast_id uuid := gen_random_uuid();
  v_count bigint;
BEGIN
  IF v_actor_id IS NULL OR NOT public.is_superadmin() THEN
    RAISE EXCEPTION 'Super Admin access required' USING ERRCODE = '42501';
  END IF;

  IF btrim(COALESCE(p_title, '')) = '' OR char_length(btrim(p_title)) > 180 THEN
    RAISE EXCEPTION 'Title is required and must be 180 characters or fewer' USING ERRCODE = '22023';
  END IF;

  IF btrim(COALESCE(p_message, '')) = '' OR char_length(btrim(p_message)) > 1000 THEN
    RAISE EXCEPTION 'Message is required and must be 1000 characters or fewer' USING ERRCODE = '22023';
  END IF;

  IF NOT COALESCE(p_clients, false)
     AND NOT COALESCE(p_admins, false)
     AND NOT COALESCE(p_superadmins, false) THEN
    RAISE EXCEPTION 'Select at least one audience' USING ERRCODE = '22023';
  END IF;

  IF NOT public.notification_target_is_safe(NULLIF(btrim(p_target_url), '')) THEN
    RAISE EXCEPTION 'Target URL must be a safe internal path' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.notifications (
    recipient_user_id,
    type,
    title,
    message,
    target_url,
    metadata,
    created_by,
    dedupe_key
  )
  SELECT
    p.id,
    left(COALESCE(NULLIF(btrim(p_type), ''), 'custom'), 80),
    left(btrim(p_title), 180),
    left(btrim(p_message), 1000),
    NULLIF(btrim(p_target_url), ''),
    jsonb_build_object(
      'broadcast_id', v_broadcast_id,
      'audience', jsonb_build_object(
        'clients', p_clients,
        'admins', p_admins,
        'superadmins', p_superadmins
      )
    ),
    v_actor_id,
    'broadcast:' || v_broadcast_id::text
  FROM public.profiles p
  WHERE (p_clients AND COALESCE(p.role, 'user') NOT IN ('admin', 'superadmin'))
     OR (p_admins AND p.role = 'admin')
     OR (p_superadmins AND p.role = 'superadmin');

  GET DIAGNOSTICS v_count = ROW_COUNT;

  SELECT COALESCE(p.name, 'Super Admin'), COALESCE(p.email, '')
  INTO v_actor_name, v_actor_email
  FROM public.profiles p
  WHERE p.id = v_actor_id;

  INSERT INTO public.admin_logs (
    admin_id,
    admin_name,
    admin_email,
    action,
    entity_type,
    entity_id,
    entity_name,
    details
  )
  VALUES (
    v_actor_id,
    COALESCE(v_actor_name, 'Super Admin'),
    COALESCE(v_actor_email, ''),
    'create',
    'notification_broadcast',
    v_broadcast_id::text,
    left(btrim(p_title), 180),
    format('Custom notification broadcast sent to %s recipient(s).', v_count)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'broadcast_id', v_broadcast_id,
    'recipient_count', v_count
  );
END;
$$;

-- --------------------------------------------------------------------------
-- Function privileges
-- --------------------------------------------------------------------------
REVOKE EXECUTE ON FUNCTION public.notification_capture_contact_submitter() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.notification_target_is_safe(text) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.enqueue_notification(uuid, text, text, text, text, text, text, text, text, text, jsonb, uuid, text, boolean) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.notification_rental_created() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.notification_rental_status_changed() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.notification_purchase_quote_created() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.notification_purchase_quote_status_changed() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.notification_contact_submitted() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.notification_chat_message_created() FROM PUBLIC, anon, authenticated;

REVOKE EXECUTE ON FUNCTION public.get_notification_unread_count() FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.mark_notification_read(uuid) FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.mark_all_notifications_read() FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.preview_notification_audience(boolean, boolean, boolean) FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.send_custom_notification(text, text, boolean, boolean, boolean, text, text) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.get_notification_unread_count() TO authenticated;
GRANT EXECUTE ON FUNCTION public.mark_notification_read(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.mark_all_notifications_read() TO authenticated;
GRANT EXECUTE ON FUNCTION public.preview_notification_audience(boolean, boolean, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.send_custom_notification(text, text, boolean, boolean, boolean, text, text) TO authenticated;

-- --------------------------------------------------------------------------
-- Realtime publication
-- --------------------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime'
        AND schemaname = 'public'
        AND tablename = 'notifications'
    ) THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE public.notifications;
    END IF;
  END IF;
END $$;
